    }
    if (ptr != nullptr) { // 冗余检查
        // More processing with ptr
    }
}
```

######## 正确示例
```cpp
void process(int* ptr) {
    if (ptr != nullptr) {
        // Do something with ptr
        // More processing with ptr
    }
}
```

