double customSqrt(double x) {
    if (x < 0) return -1; // 处理错误输入
    return x / 2; // 简单的估算，不准确
}

int main() {
    std::cout << customSqrt(16) << std::endl;
    return 0;
}
```

######## Correct Example
```cpp
// 正确示例：使用标准库实现平方根计算
#include <iostream>
#include <cmath>

