rules.content:
####### 规则概述
该规则旨在鼓励使用C++标准模板库（STL）中的算法，以提高代码的简洁性和可读性。

######## 规则意义
使用STL算法可以减少代码的复杂性，避免手动编写重复的逻辑，同时利用STL的优化实现提升性能和保障安全性。

######## 错误示例
'''cpp
#include <vector>
#include <iostream>

void sortVector(std::vector<int>& vec) {
    for (size_t i = 0; i < vec.size(); ++i) {
        for (size_t j = i + 1; j < vec.size(); ++j) {
            if (vec[i] > vec[j]) {
                std::swap(vec[i], vec[j]);
            }
        }
    }
}

int main() {
    std::vector<int> myVec = {5, 3, 8, 1, 2};
    sortVector(myVec);
    for (int num : myVec) {
        std::cout << num << " ";
    }
    return 0;
}
'''

######## 正确示例
'''cpp
#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> myVec = {5, 3, 8, 1, 2};
    std::sort(myVec.begin(), myVec.end());
    for (int num : myVec) {
        std::cout << num << " ";
    }
    return 0;
}
'''

rules.content_en:
